insert  into `care_record`(`record_id`,`elderly_id`,`creator_id`,`care_type`,`care_content`,`care_time`,`start_time`,`approved_time`,`status`,`image_url`,`remark`,`create_by`,`create_time`,`update_by`,`update_time`,`del_flag`) values (4001,1,103,'1','协助老人进食，确保营养均衡','2026-03-24 00:00:00','2026-03-24 00:00:00','2026-03-24 00:00:00','1','/profile/upload/2026/03/24/执行-助餐@4x_20260324151713A002.jpg','需要注意老人的饮食偏好','admin','2026-03-24 14:42:59','','2026-04-21 20:30:06','0'),(4002,2,103,'1','协助老人起床、穿衣、洗漱','2026-03-24 00:00:00','2026-03-24 00:00:00','2026-03-24 00:00:00','1','/profile/upload/2026/03/24/执行-翻身拍背@4x_20260324151749A004.jpg','老人行动不便，需要耐心协助','admin','2026-03-24 14:42:59','','2026-03-24 15:17:55','0'),(4003,3,105,'2','协助老人洗澡、理发','2026-03-24 00:00:00','2026-03-31 00:00:00','2026-03-31 00:00:00','1','/profile/upload/2026/03/31/执行-洗头@4x_20260331213226A004.jpg','注意水温，避免老人感冒','admin','2026-03-24 14:42:59','','2026-03-31 21:32:52','0'),(4004,1,105,'3','协助老人进行康复训练','2026-03-24 00:00:00','2026-03-30 00:00:00','2026-03-30 00:00:00','1','/profile/upload/2026/03/31/执行-复建运动@4x_20260331213350A005.jpg','按照康复计划进行训练','admin','2026-03-24 14:42:59','','2026-03-31 21:34:12','0'),(4005,2,103,'4','与老人聊天，缓解孤独感','2026-03-24 00:00:00','2026-04-13 00:00:00','2026-04-13 00:00:00','1','/profile/upload/2026/04/13/执行-谈心@4x_20260413213330A001.jpg','关注老人的情绪变化','admin','2026-03-24 14:42:59','','2026-04-13 21:33:32','0'),(4006,3,105,'0','协助老人进食，确保营养均衡','2026-03-25 00:00:00','2026-03-29 00:00:00','2026-03-31 00:00:00','1','/profile/upload/2026/03/31/执行-助餐@4x_20260331213420A006.jpg','老人有糖尿病，需要控制饮食','admin','2026-03-24 14:42:59','','2026-03-31 21:34:47','0'),(4007,1,105,'1','协助老人起床、穿衣、洗漱','2026-03-25 00:00:00','2026-03-28 00:00:00','2026-03-28 00:00:00','1','/profile/upload/2026/03/31/执行-整体床铺@4x_20260331213647A007.jpg','老人视力不好，需要特别注意','admin','2026-03-24 14:42:59','','2026-03-31 21:37:25','0'),(4008,2,103,'3','协助老人进行康复训练','2026-03-26 00:00:00','2026-04-13 00:00:00','2026-04-13 00:00:00','2',NULL,'重点训练