/*Table structure for table `doctor_handover` */

DROP TABLE IF EXISTS `doctor_handover`;

CREATE TABLE `doctor_handover` (
  `handover_id` bigint NOT NULL AUTO_INCREMENT COMMENT '交接记录ID',
  `current_doctor_id` bigint NOT NULL COMMENT '当前医生ID',
  `next_doctor_id` bigint NOT NULL COMMENT '待交接医生ID',
  `start_time` datetime NOT NULL COMMENT '上班时间',
  `end_time` datetime DEFAULT NULL COMMENT '下班时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0待交接 1已交接 2已完成）',
  `overview` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '当前情况概述',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`handover_id`),
  KEY `idx_current_doctor_id` (`current_doctor_id`),
  KEY `idx_next_doctor_id` (`next_doctor_id`),
  KEY `idx_status` (`status`),
  CONSTRAINT `fk_doctor_handover_current_doctor` FOREIGN KEY (`current_doctor_id`) REFERENCES `sys_user` (`user_id`),
  CONSTRAINT `fk_doctor_handover_next_doctor` FOREIGN KEY (`next_doctor_id`) REFERENCES `sys_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6049 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='医生交班记录表';

/*Data for the table `doctor_handover` */

insert  into `doctor_handover`(`handover_id`,`current_doctor_id`,`next_doctor_id`,`start_time`,`end_time`,`status`,`overview`,`create_by`,`create_time`,`update_by`,`update_time`,`del_flag`) values (6004,102,107,'2026-03-30 08:00:00','2026-03-30 17:00:00','1','日间接诊高龄老人15名，3名高血压患者按时服药，血糖监测数据已归档，无突发急症。','admin','2026-03-30 17:05:00','',NULL,'0'),(6005,107,108,'2026-03-30 00:00:00','2026-03-31 00:00:00','1','夜间重点监护慢病卧床老人，留意吸氧老人血氧变化，夜间备应急降压药品，及时记录体征。','admin','2026-03-30 16:50:00','','2026-04-13 22:39:39','0'),(6006,108,108,'2026-03-31 00:00:00','2026-03-31 00:00:00','1','需跟进2位术后康复老人复查，调整理疗用药剂量，同步康复记录至老人健康档案。','admin','2026-03-31 07:55:00','','2026-04-13 22:35:17','0'),(6007,109,102,'2026-03-29 08:00:00','2026-03-29 17:00:00','1','完成本周老人常规体检筛查，异常指标已单独标注，已告知家属注意日常养护事项。','admin','2026-03-29 17:10:00','',NULL,'0'),(6008,102,107,'2026-04-01 08:00:00','2026-04-01 17:00:00','1','日间接诊新入院老人2名（吴桂芳、王淑珍），完成入院体检及用药方案制定。现有慢病管理老人15名，今日血压血糖监测无异常，3名骨关节疼痛老人已安排艾灸理疗。','admin','2026-04-01 17:05:00','',NULL,'0'),(6009,107,108,'2026-04-01 17:00:00','2026-04-02 08:00:00','1','夜班重点监护：104房间三位老人体温略有波动，已持续观察。刘翠华老人夜间入睡困难，给予助眠指导。周医生明早跟进体检报告。','admin','2026-04-01 17:10:00','',NULL,'0'),(6010,108,102,'2026-04-02 08:00:00','2026-04-02 17:00:00','1','上午完成老人季度健康体检补录，发现2名老人血红蛋白偏低，已通知家属补充营养方案。下午配合康复师调整张有财认知训练计划。','admin','2026-04-02 17:02:00','',NULL,'0'),(6011,102,107,'2026-04-02 17:00:00','2026-04-03 08:00:00','1','夜间接诊1名发热老人（孙雷，体温38.2℃），已给予退热处理并持续监测体温变化至凌晨3点，退热后稳定。请日班重点关注孙雷老人状态。','admin','2026-04-02 17:05:00','',NULL,'0'),(6012,107,108,'2026-04-03 08:00:00','2026-04-03 17:00:00','1','日班接孙雷老人发热事件持续观察，复查体温正常，精神状态恢复。李秀英老人今日主诉轻微头晕，血压测量偏高（148/92），调整降压药用量，待观察。','admin','2026-04-03 17:00:00','',NULL,'0'),(6013,108,109,'2026-04-03 17:00:00','2026-04-04 08:00:00','1','夜间整体平稳，各老人体征数据正常记录。完成本周排班汇总及药品库存核查，心电图检测仪电极片需补充。明日安排老人集体健康讲座，请提前通知。','admin','2026-04-03 17:05:00','',NULL,'0'),(6014,109,102,'2026-04-04 08:00:00','2026-04-04 17:00:00','1','本周健康讲座（高血糖饮食管理）顺利开展，共有8位老人及家属参与，反响良好。完成老人王淑珍糖尿病食谱制定，已交接给护理组执行。','admin','