/*Table structure for table `medical_order` */

DROP TABLE IF EXISTS `medical_order`;

CREATE TABLE `medical_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '医嘱ID',
  `elderly_id` bigint NOT NULL COMMENT '老人ID ',
  `order_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '医嘱内容',
  `medication_advice` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '用药建议',
  `doctor_id` bigint NOT NULL COMMENT '医生ID ',
  `order_date` datetime NOT NULL COMMENT '医嘱日期',
  `medication_id` bigint DEFAULT NULL COMMENT '用药表ID ',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0正常 1停用）',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`order_id`),
  KEY `idx_elderly_id` (`elderly_id`)
) ENGINE=InnoDB AUTO_INCREMENT=2006 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='医嘱表';

