/*Table structure for table `medication_record` */

DROP TABLE IF EXISTS `medication_record`;

CREATE TABLE `medication_record` (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '用药记录ID',
  `order_id` bigint NOT NULL COMMENT '医嘱ID ',
  `medicine_id` bigint NOT NULL COMMENT '药品ID ',
  `scheduled_time` datetime NOT NULL COMMENT '计划用药时间',
  `actual_time` datetime DEFAULT NULL COMMENT '实际用药时间',
  `nurse_id` bigint NOT NULL COMMENT '分配护工ID',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡图片URL',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '任务状态（0待执行 1已完成 2异常）',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`record_id`),
  KEY `idx_order_id` (`order_id`),
  KEY `idx_medicine_id` (`medicine_id`),
  KEY `idx_nurse_id` (`nurse_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3011 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用药表';

