/*Table structure for table `medicine` */

DROP TABLE IF EXISTS `medicine`;

CREATE TABLE `medicine` (
  `medicine_id` bigint NOT NULL AUTO_INCREMENT COMMENT '药品ID',
  `medicine_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '药品名称',
  `price` decimal(10,2) NOT NULL COMMENT '药品价格',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '药品说明',
  `stock` int NOT NULL COMMENT '药品库存',
