/*Table structure for table `project_order` */

DROP TABLE IF EXISTS `project_order`;

CREATE TABLE `project_order` (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目单ID',
  `elderly_id` bigint NOT NULL COMMENT '关联的老人ID',
  `item_id` bigint NOT NULL COMMENT '服务项目ID',
  `creator_id` bigint NOT NULL COMMENT '开单人用户ID',
  `creator_role` tinyint NOT NULL COMMENT '开单人角色：1-管理员,2-医生',
  `auditor_id` bigint DEFAULT NULL COMMENT '审核人用户ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '状态：0-草稿,1-待审核,2-已通过,3-已驳回',
  `created_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '开单时间',
  `submitted_time` datetime DEFAULT NULL COMMENT '提交审核时间',
  `approved_time` datetime DEFAULT NULL COMMENT '审核通过时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '开单备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  PRIMARY KEY (`order_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='项目单主表';

