/*Table structure for table `sys_feedback` */

DROP TABLE IF EXISTS `sys_feedback`;

CREATE TABLE `sys_feedback` (
  `feedback_id` bigint NOT NULL AUTO_INCREMENT COMMENT '反馈ID',
  `sender_id` bigint NOT NULL COMMENT '发送者ID',
  `sender_name` varchar(64) NOT NULL COMMENT '发送者名称',
  `sender_role` varchar(100) NOT NULL COMMENT '发送者角色',
  `receiver_id` bigint DEFAULT NULL COMMENT '接收者ID（null表示全体成员）',
  `receiver_name` varchar(64) DEFAULT NULL COMMENT '接收者名称',
  `receiver_role` varchar(100) DEFAULT NULL COMMENT '接收者角色',
  `type` char(1) NOT NULL COMMENT '类型（0-留言，1-建议）',
  `content` varchar(1000) NOT NULL COMMENT '内容',
  `status` char(1) DEFAULT '0' COMMENT '状态（0-未读，1-已读）',
  `parent_id` bigint DEFAULT NULL COMMENT '父反馈ID，用于回复功能',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`feedback_id`),
  KEY `idx_sender_id` (`sender_id`),
  KEY `idx_receiver_id` (`receiver_id`),
  KEY `idx_type` (`type`),
  KEY `idx_status` (`status`),
  KEY `idx_create_time` (`create_time`),
  KEY `idx_parent_id` (`parent_id`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='沟通反馈表';

/*Data for the table `sys_feedback` */

insert  into `sys_feedback`(`feedback_id`,`sender_id`,`sender_name`,`sender_role`,`receiver_id`,`receiver_name`,`receiver_role`,`type`,`content`,`status`,`parent_id`,`create_by`,`create_time`,`update_by`,`update_time`) values (1,1,'admin','超级管理员',NULL,NULL,NULL,'0','这是一条给全体成员的通知','1',NULL,'','2026-03-30 11:15:38','','2026-03-30 13:46:46'),(4,1,'GuangWen','超级管理员',102,'王医生',NULL,'0','王医生，今天钱爷爷的家属找您沟通过了吗\n','1',NULL,'','2026-03-30 11:20:19','','2026-03-30 13:54:11'),(5,102,'王医生','医生',1,'GuangWen','超级管理员','0','今天没有来，家属说明天来','3',4,'','2026-03-30 13:48:10','','2026-03-30 20:20:37'),(6,1,'GuangWen','超级管理员',102,'王医生','医生','0','收到','1',5,'','2026-03-30 13:52:03','','2026-03-30 13:52:37'),(8,1,'GuangWen','超级管理员',102,'王医生','医生','0','家属来了通知我','1',5,'','2026-03-30 14:20:29','','2026-03-30 14:20:59'),(9,114,'吴女士','家属',105,'刘护工',NULL,'0','刘阿姨你好，我是吴爷爷的家属，我加老人乳糖不耐受，不能喝牛奶，日后还请多多照顾，谢谢！','1',NULL,'','2026-03-30 19:55:09','','2026-03-31 14:12:03'),(10,102,'王医生','医生',102,'王医生','医生','0','好的，光稳','0',5,'','2026-03-30 20:20:37','','2026-03-30 20:20:37'),(11,115,'郑先生','家属',103,'李护工',NULL,'0','先生，我家老人托付给您了！','0',NULL,'','2026-04-17 17:16:01','','2026-04-17 17:16:01'),(12,114,'吴女士','家属',103,'李护工','护工','0','李阿姨您好，我母亲吴桂芳有心脏病，麻烦您在帮她洗澡时注意水温不要太高，时间也不要太长，谢谢您细心照顾！','0',NULL,'','2026-03-31 10:30:00','','2026-04-21 18:07:17'),(13,113,'钱先生','家属',105,'刘护工','护工','0','刘阿姨您好，我父亲钱多多有糖尿病，上次医生说要注意饮食，请问本周的控糖餐是怎么安排的？另外他晚上容易饿，可以给他加点无糖饼干吗？','0',NULL,'','2026-04-01 09:15:00','','2026-04-21 18:07:17'),(14,115,'郑先生','家属',105,'刘护工','护工','0','刘阿姨，我父亲陈福生这几天精神状态好多了，上次您帮忙修剪指甲、整理仪容，他自己都说舒服，感谢您的耐心照顾！','0',NULL,'','2026-04-03 16:20:00','','2026-04-21 18:07:17'),(15,118,'张伟','家属',110,'韩护工','护工','0','韩阿姨您好，我想了解一下张有财最近的语言训练情况。上次医生说开始吃药了，日常生活有没有什么变化？方便的时候麻烦您说一下，谢谢！','0',NULL,'','2026-04-06 11:00:00','','2026-04-21 18:07:17'),(16,117,'刘芳','家属',111,'卫护工','护工','0','卫阿姨您好，我想问一下刘翠华的膝盖康复情况。上次听说停了高强度训练，改成温水浴疗法，现在膝盖还疼得厉害吗？她晚上睡眠怎么样？','0',NULL,'','2026-04-12 14:30:00','','2026-04-21 18:07:17'),(17,119,'王丽','家属',112,'唐护工','护工','0','唐阿姨辛苦了！我母亲王淑珍的指甲修剪好了，她说您特别细心，还帮忙涂了护手霜，真的很感动，感谢您平时对我母亲的照顾！','0',NULL,'','2026-04-15 10:00:00','','2026-04-21 18:07:17'),(18,114,'吴女士','家属',101,'养老管理员','养老管理员','0','管理员您好，我之前注册了账号想查看母亲的身体健康报告，但是登录后看不到详细数据，请问家属账号能看到哪些内容？需要怎么操作？','0',NULL,'','2026-04-08 09:00:00','','2026-04-21 18:07:17'),(19,120,'周明','家属',101,'养老管理员','养老管理员','0','管理员您好，我有几点建议：1）希望app上能直接查看老人的每日三餐情况；2）护工更换时希望能提前通知家属；3）希望每周能收到一份老人生活简报。供参考！','0',NULL,'','2026-04-10 15:00:00','','2026-04-21 18:07:17'),(20,102,'王医生','医生',114,'吴女士','家属','0','吴女士您好，我是王医生。4月6日晚上吴桂芳老人出现过一次胸闷症状，我们及时处理后稳定了。现在拟安排她4月10日（下周一）上午到社区卫生服务中心做心脏复查，届时请家属陪同。如有特殊情况请及时联系。','0',NULL,'','2026-04-07 10:00:00','','2026-04-21 18:07:17'),(21,107,'陈医生','医生',118,'张伟','家属','0','张伟先生您好，陈医生跟进张有财老人最新情况：目前已开始服用盐酸多奈哌齐片（治疗老年痴呆），认知功能评估较上周略有改善，语言训练效果初显。继续维持当前治疗方案，请放心，有任何变化我们会第一时间通知您。','0',NULL,'','2026-04-18 16:00:00','','2026-04-21 18:07:17'),(22,102,'王医生','医生',113,'钱先生','家属','0','钱先生您好，收到您的咨询。钱多多的血糖本周控制得不错（空腹5.8-6.2 mmol/L之间），符合目标范围。二甲双胍按原剂量服用，饮食方面建议少食多餐，无糖饼干可以适量食用，建议选用正规无糖食品。如有其他问题欢迎随时咨询。','0',NULL,'','2026-04-02 09:30:00','','2026-04-21 18:07:17'),(23,108,'周医生','医生',117,'刘芳','家属','0','刘芳您好，关于刘翠华老人的膝关节情况：停止高强度训练改为温水浴疗法后，老人反映疼痛有所缓解，夜间睡眠质量也有改善。目前配合服用氨基葡萄糖胶囊营养软骨，预计2-3周后评估是否可以逐步恢复部分训练强度。','0',NULL,'','2026-04-13 11:00:00','','2026-04-21 18:07:17'),(24,103,'李护工','护工',102,'王医生','医生','0','王医生您好，今天下午帮吴桂芳奶奶洗完澡后，给她量了血压，138/88，比平时略高一点，奶奶说有点累，没有胸闷症状。已告知奶奶多休息，密切观察中，特此汇报。','0',NULL,'','2026-04-14 16:30:00','','2026-04-21 18:07:17'),(25,110,'韩护工','护工',107,'陈医生','医生','0','陈医生您好，今晚张有财老人有些情绪波动，大概20:30左右开始认人困难加剧，护理员安抚了一阵后情绪稳定下来了。目前已入睡，无其他异常。请医生明天评估一下是否需要调整用药方案。','0',NULL,'','2026-04-10 21:00:00','','2026-04-21 18:07:17'),(26,105,'刘护工','护工',108,'周医生','医生','0','周医生好，陈福生老人这几天晚上起夜比较频繁（3-4次），白天精神状态还可以，但有些担心是否需要检查一下前列腺或者泌尿系统？请问需要安排进一步检查吗？','0',NULL,'','2026-04-05 08:00:00','','2026-04-21 18:07:17'),(27,111,'卫护工','护工',102,'王医生','医生','0','王医生，本周老人的服药协助工作汇报：共协助服药47人次，无漏服情况。钱多多老人服用二甲双胍后食欲略有下降，已通知饮食组调整餐食；周扒皮老人降压药服用规律，血压控制良好。有问题随时联系。','0',NULL,'','2026-04-13 08:30:00','','2026-04-21 18:07:17'),(28,102,'王医生','医生',103,'李护工','护工','0','李护工您好，收到家属反馈。吴桂芳老人有心脏病史，请协助沐浴时注意：①水温控制在38℃以下；②时间不超过15分钟；③避免空腹或刚服完药后马上洗；④如有不适立即停止并通知当班医生。感谢您的配合！','0',NULL,'','2026-04-01 11:00:00','','2026-04-21 18:07:17'),(29,107,'陈医生','医生',110,'韩护工','护工','0','韩护工，张有财老人已从4月12日起开始服用盐酸多奈哌齐片，请在日常护理中留意：①有无恶心、食欲下降；②有无心率加快；③情绪波动情况有无改善。如有任何异常及时告知，我会调整方案。','0',NULL,'','2026-04-12 09:00:00','','2026-04-21 18:07:17'),(30,108,'周医生','医生',105,'刘护工','护工','0','刘护工您好，已了解陈福生老人夜间起夜频繁的情况。本周已安排前列腺专项检查，结果正常。目前建议：①晚间适当减少饮水量；②协助如厕时注意安全防止跌倒；③持续观察记录起夜次数。必要时再与家属沟通就医安排。','0',NULL,'','2026-04-06 10:30:00','','2026-04-21 18:07:17'),(31,101,'养老管理员','养老管理员',103,'李护工','护工','0','各位护工同事：近期护理质量检查发现，部分护理记录的\"情况描述\"字段填写过于简略（如只写\"正常\"）。请按规范填写：①记录实际完成的护理内容；②如有特殊情况须详细描述；③每日护理记录须在当班结束前完成填写。谢谢配合！','0',NULL,'','2026-04-08 08:00:00','','2026-04-21 18:07:17'),(32,101,'养老管理员','养老管理员',105,'刘护工','护工','0','通知：4月份养老服务质量内部检查将于4月25日（下周六）上午进行，请各位护工提前整理好个人负责老人的护理文书、药品管理台账及护理设备维护记录。检查当天请保持通讯畅通。','0',NULL,'','2026-04-20 09:00:00','','2026-04-21 18:07:17'),(33,101,'养老管理员','养老管理员',111,'卫护工','护工','0','通知：端午节（5月31日）将举办\"粽香暖夕阳\"主题活动，计划包粽子、制作香囊、文艺表演等，现征集护工及老人家属志愿者参与，有意者请在本周内向管理员报名。谢谢！','0',NULL,'','2026-04-18 14:00:00','','2026-04-21 18:07:17'),(34,109,'孙医生','医生',107,'陈医生','医生','0','陈医生好，今晚上班看了下各老人情况，整体稳定，重点关注：①孙雷老人（206房）白天有轻微咳嗽，晚上留意是否加重；②王淑珍老人睡眠评分偏低，如有失眠及时处理。辛苦了！','0',NULL,'','2026-04-14 17:05:00','','2026-04-21 18:07:17'),(35,102,'王医生','医生',107,'陈医生','医生','0','陈医生，明天（4月22日）上午区人民医院心内科专家来养老院坐诊（9:00-11:00），吴桂芳和王淑珍家属已预约复诊，请提前通知老人和家属带好病历本在约定时间到医务室等候。','0',NULL,'','2026-04-21 16:00:00','','2026-04-21 18:07:17'),(36,101,'养老管理员','养老管理员',102,'王医生','医生','0','王医生，本月医务人员绩效考核数据表请于4月28日前提交至管理员处，包括：接诊人次、慢病管理人数、培训参与情况及老人满意度数据。如有疑问请联系管理员。','0',NULL,'','2026-04-21 10:00:00','','2026-04-21 18:07:17');

/*Table structure for table `sys_floor_dept` */

DROP TABLE IF EXISTS `sys_floor_dept`;

CREATE TABLE `sys_floor_dept` (
  `floor_dept_id` bigint NOT NULL AUTO_INCREMENT COMMENT '楼层科室ID',
  `floor` bigint NOT NULL COMMENT '楼层号',
  `dept_name` varchar(100) NOT NULL COMMENT '科室名称',
  `dept_desc` varchar(500) DEFAULT NULL COMMENT '科室简介',
  `status` char(1) DEFAULT '0' COMMENT '状态（0-正常，1-停用）',
  `order_num` int DEFAULT '0' COMMENT '显示顺序',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` char(1) DEFAULT '0' COMMENT '删除标志（0-正常，2-删除）',
  PRIMARY KEY (`floor_dept_id`),
  KEY `idx_floor` (`floor`),
  KEY `idx_status` (`status`),
  KEY `idx_del_flag` (`del_flag`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='颐养结合养老服务中心楼层科室表';

/*Data for the table `sys_floor_dept` */

insert  into `sys_floor_dept`(`floor_dept_id`,`floor`,`dept_name`,`dept_desc`,`status`,`order_num`,`create_by`,`create_time`,`update_by`,`update_time`,`del_flag`) values (1,1,'生活照料区','为老人提供日常生活照料、起居护理等服务','0',1,'','2026-03-30 10:09:08','','2026-03-30 10:09:08','0'),(2,1,'餐饮服务区','提供营养均衡的餐饮服务，满足老人的饮食需求','0',2,'','2026-03-30 10:09:08','','2026-03-30 10:09:08','0'),(3,2,'康复护理区','提供康复训练、护理服务，帮助老人恢复身体功能','0',3,'','2026-03-30 10:09:08','','2026-03-30 10:53:30','0'),(4,2,'医疗保健区','提供基本医疗服务、健康监测等','0',4,'','2026-03-30 10:09:08','','2026-03-30 10:53:32','0'),(5,3,'娱乐活动区','提供各种娱乐活动、文化课程等，丰富老人的精神生活','0',5,'','2026-03-30 10:09:08','','2026-03-30 10:53:33','0'),(6,3,'安宁疗护区','为临终老人提供舒适、有尊严的照护服务','0',6,'','2026-03-30 10:09:08','','2026-03-30 10:53:34','0'),(7,4,'行政办公区','中心管理办公区域','0',7,'','2026-03-30 10:09:08','','2026-03-30 10:53:36','0'),(8,4,'员工休息区','员工休息、培训区域','0',8,'','2026-03-30 10:09:08','','2026-03-30 10:53:37','0');

/*Table structure for table `sys_job` */

DROP TABLE IF EXISTS `sys_job`;

CREATE TABLE `sys_job` (
  `job_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务ID',
  `job_name` varchar(64) NOT NULL DEFAULT '' COMMENT '任务名称',
  `job_group` varchar(64) NOT NULL DEFAULT 'DEFAULT' COMMENT '任务组名',
  `invoke_target` varchar(500) NOT NULL COMMENT '调用目标字符串',
  `cron_expression` varchar(255) DEFAULT '' COMMENT 'cron执行表达式',
  `misfire_policy` varchar(20) DEFAULT '3' COMMENT '计划执行错误策略（1立即执行 2执行一次 3放弃执行）',
  `concurrent` char(1) DEFAULT '1' COMMENT '是否并发执行（0允许 1禁止）',
  `status` char(1) DEFAULT '0' COMMENT '状态（0正常 1暂停）',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注信息',
  PRIMARY KEY (`job_id`,`job_name`,`job_group`)
) ENGINE=InnoDB AUTO_INCREMENT=100 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='定时任务调度表';

/*Data for the table `sys_job` */

insert  into `sys_job`(`job_id`,`job_name`,`job_group`,`invoke_target`,`cron_expression`,`misfire_policy`,`concurrent`,`status`,`create_by`,`create_time`,`update_by`,`update_time`,`remark`) values (1,'系统默认（无参）','DEFAULT','ryTask.ryNoParams','0/10 * * * * ?','3','1','1','admin','2025-12-17 14:12:19','',NULL,''),(2,'系统默认（有参）','DEFAULT','ryTask.ryParams(\'ry\')','0/15 * * * * ?','3','1','1','admin','2025-12-17 14:12:19','',NULL,''),(3,'系统默认（多参）','DEFAULT','ryTask.ryMultipleParams(\'ry\', true, 2000L, 316.50D, 100)','0/20 * * * * ?','3','1','1','admin','2025-12-17 14:12:19','',NULL,'');

/*Table structure for table `sys_job_log` */

DROP TABLE IF EXISTS `sys_job_log`;

CREATE TABLE `sys_job_log` (
  `job_log_id` bigint NOT NULL AUTO_INCREMENT COMMENT '任务日志ID',
  `job_name` varchar(64) NOT NULL COMMENT '任务名称',
  `job_group` varchar(64) NOT NULL COMMENT '任务组名',
  `invoke_target` varchar(500) NOT NULL COMMENT '调用目标字符串',
  `job_message` varchar(500) DEFAULT NULL COMMENT '日志信息',
  `status` char(1) DEFAULT '0' COMMENT '执行状态（0正常 1失败）',
  `exception_info` varchar(2000) DEFAULT '' COMMENT '异常信息',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`job_log_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='定时任务调度日志表';

/*Data for the table `sys_job_log` */

/*Table structure for table `sys_logininfor` */

DROP TABLE IF EXISTS `sys_logininfor`;

CREATE TABLE `sys_logininfor` (
  `info_id` bigint NOT NULL AUTO_INCREMENT COMMENT '访问ID',
  `user_name` varchar(50) DEFAULT '' COMMENT '用户账号',
  `ipaddr` varchar(128) DEFAULT '' COMMENT '登录IP地址',
  `login_location` varchar(255) DEFAULT '' COMMENT '登录地点',
  `browser` varchar(50) DEFAULT '' COMMENT '浏览器类型',
  `os` varchar(50) DEFAULT '' COMMENT '操作系统',
  `status` char(1) DEFAULT '0' COMMENT '登录状态（0成功 1失败）',
  `msg` varchar(255) DEFAULT '' COMMENT '提示消息',
  `login_time` datetime DEFAULT NULL COMMENT '访问时间',
  PRIMARY KEY (`info_id`),
  KEY `idx_sys_logininfor_s` (`status`),
  KEY `idx_sys_logininfor_lt` (`login_time`)
